PREFIX in: <http://data.world/schema/insurance/>

SELECT (xsd:decimal(?totalPremium) / xsd:decimal(?policyCount) AS ?averagePolicySize)
WHERE {
  {
    SELECT (SUM(xsd:decimal(?amt)) AS ?totalPremium)
    WHERE {
      SERVICE <mapped> {
        ?pcd a in:PolicyCoverageDetail ;
             in:hasPolicy ?policy ;
             in:hasPremiumAmount ?premium .
        ?premium in:premiumAmount ?amt .
      }
    }
  }
  {
    SELECT (COUNT(DISTINCT ?policy) AS ?policyCount)
    WHERE {
      SERVICE <mapped> {
        ?pcd a in:PolicyCoverageDetail ;
             in:hasPolicy ?policy .
      }
    }
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?policyNumber ?policyHolderId ?premiumAmount
       (COALESCE(SUM(?lossPaymentAmt), 0) +
        COALESCE(SUM(?lossReserveAmt), 0) +
        COALESCE(SUM(?expensePaymentAmt), 0) +
        COALESCE(SUM(?expenseReserveAmt), 0) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:against ?coverage .

    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy ;
              in:hasPremiumAmount ?premium .

    ?policy a in:Policy ;
            in:policyNumber ?policyNumber ;
            in:hasPolicyHolder ?policyHolder .

    ?policyHolder a in:PolicyHolder ;
                  in:policyHolderId ?policyHolderId .

    ?premium a in:Premium ;
             in:premiumAmount ?premiumAmount .

    OPTIONAL {
      ?claim in:hasLossPayment ?lp .
      ?lp in:lossPaymentAmount ?lossPaymentAmt .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lr .
      ?lr in:lossReserveAmount ?lossReserveAmt .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?ep .
      ?ep in:expensePaymentAmount ?expensePaymentAmt .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?er .
      ?er in:expenseReserveAmount ?expenseReserveAmt .
    }
  }
}
GROUP BY ?claimNumber ?policyNumber ?policyHolderId ?premiumAmount
ORDER BY ?claimNumber

PREFIX in: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?policyHolderId ?policyNumber (SUM(xsd:decimal(?premiumValue)) AS ?totalPremiumAmount)
WHERE {
  SERVICE <mapped> {
    ?policyCoverageDetail a in:PolicyCoverageDetail ;
                          in:hasPolicy ?policy ;
                          in:hasPremiumAmount ?premium .

    ?policy a in:Policy ;
            in:policyNumber ?policyNumber ;
            in:hasPolicyHolder ?policyHolder .

    ?policyHolder a in:PolicyHolder ;
                  in:policyHolderId ?policyHolderId .

    ?premium a in:Premium ;
             in:premiumAmount ?premiumValue .
  }
}
GROUP BY ?policyHolderId ?policyNumber
ORDER BY ?policyHolderId ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?policyNumber ?policyHolder ?premiumAmountPaid ?catastrophe ?agent
       ?lossPaymentAmount ?lossReserveAmount ?expensePaymentAmount ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:against ?pcd .

    ?pcd in:hasPolicy ?policy .
    ?policy in:policyNumber ?policyNumber .

    OPTIONAL {
      ?policy in:hasPolicyHolder ?ph .
      OPTIONAL { ?ph in:policyHolderId ?policyHolder }
    }

    OPTIONAL {
      ?pcd in:hasPremiumAmount ?premium .
      OPTIONAL { ?premium in:premiumAmount ?premiumAmountPaid }
    }

    OPTIONAL {
      ?claim in:hasCatastrophe ?catObj .
      OPTIONAL { ?catObj in:catastropheName ?catastrophe }
    }

    OPTIONAL {
      ?policy in:soldByAgent ?agentObj .
      OPTIONAL { ?agentObj in:agentId ?agent }
    }

    OPTIONAL {
      ?claim in:hasLossPayment ?lp .
      ?lp in:lossPaymentAmount ?lossPaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lr .
      ?lr in:lossReserveAmount ?lossReserveAmount .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?ep .
      ?ep in:expensePaymentAmount ?expensePaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?er .
      ?er in:expenseReserveAmount ?expenseReserveAmount .
    }
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?agentId ?policyNumber ?claimNumber ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?policy in:soldByAgent ?agent ;
            in:policyNumber ?policyNumber .

    ?agent in:agentId ?agentId .

    ?coverage in:hasPolicy ?policy .

    ?claim in:against ?coverage ;
           in:claimNumber ?claimNumber ;
           in:hasExpenseReserve ?expenseReserve .

    ?expenseReserve in:expenseReserveAmount ?expenseReserveAmount .
  }
}
ORDER BY ?agentId ?policyNumber ?claimNumber
